me="popup_click_type"><option value="none">No Action</option><option value="enquiry">Enquiry Page</option><option value="whatsapp">WhatsApp</option><option value="custom">Custom URL</option></select></label><label>Custom URL<input name="popup_click_url" value="<?=sh($s['popup_click_url']??'')?>"></label></div><div class="form-grid"><label>Start Date<input type="date" name="popup_start_date" value="<?=sh($s['popup_start_date']??'')?>"></label><label>End Date<input type="date" name="popup_end_date" value="<?=sh($s['popup_end_date']??'')?>"></label><label>Cooldown Hours<input type="number" name="popup_cooldown_hours" min="1" max="720" value="<?=sh($s['popup_cooldown_hours']??24)?>"></label></div><div class="preview-grid"><div><strong>Desktop Preview</strong><div class="popup-preview desktop" id="desktopPreview"></div></div><div><strong>Mobile Preview</strong><div class="popup-preview mobile" id="mobilePreview"></div></div></div><button class="primary-button" name="action" value="save_popup">Save Changes</button></form><?php endif;?></div><?php endif;?></main></div><script src="settings.js" defer></script></body></html>
